// Generated by OrchestKit Claude Plugin
// Created: 2026-08-11

/**
 * Guard-denial circuit breaker: count how many times THIS session has been
 * denied for THIS exact command, so the guard can say so out loud (#3422).
 *
 * A blocked tool call means adjust, never re-emit. On 2026-08-10 a session
 * re-sent one byte-identical denied git command 8 consecutive times (and 4
 * in a second repo). The guard was correct on every one of them; nothing in
 * the rendered denial distinguished the 8th from the 1st, so the loop had no
 * in-band signal to break it. Counting is the signal.
 *
 * Scope and lifetime:
 *   • Keyed by (session, exact command bytes) — a reworded command is a NEW
 *     attempt and correctly starts over at 1. That is the point: changing the
 *     command's SHAPE is the desired response to a denial.
 *   • Entries older than the TTL are dropped on read, so a command denied
 *     this morning does not escalate an unrelated retry this afternoon.
 *   • The file is capped, so a long session cannot grow it without bound.
 *
 * Fail-open by construction: every path returns a usable count and swallows
 * fs errors. A broken counter must degrade to today's plain deny — it must
 * never crash the hook and must never turn a deny into an allow.
 */

import { existsSync, mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { homedir } from 'node:os';
import { fnv1aHash } from './output.js';

/** Entries stop counting toward escalation after this long. */
export const DENIAL_TTL_MS = 30 * 60 * 1000; // 30 minutes

/** Hard cap on tracked commands per session file. */
const MAX_ENTRIES = 50;

/** One tracked command's denial history. */
export interface DenialEntry {
  /** How many times this exact command has been denied. */
  count: number;
  /** Epoch ms of the first denial. */
  firstMs: number;
  /** Epoch ms of the most recent denial. */
  lastMs: number;
  /**
   * Leading bytes of the command. `fnv1aHash` is 32-bit, so keys can in
   * principle collide; storing a prefix lets us detect that and start a
   * fresh count rather than escalate on an unrelated command.
   */
  head: string;
}

/** The on-disk shape: hash -> entry. */
export type DenialLedger = Record<string, DenialEntry>;

/** How many command bytes to retain for collision disambiguation. */
const HEAD_LEN = 80;

/** Absolute path of the denial ledger for one session. */
export function getDenialLedgerPath(
  repoSlug: string,
  sessionId: string,
  home: string = homedir(),
): string {
  return join(home, '.claude', 'state', 'orchestkit', repoSlug, `denials-${sessionId}.json`);
}

function readLedger(path: string): DenialLedger {
  try {
    if (!existsSync(path)) return {};
    const parsed: unknown = JSON.parse(readFileSync(path, 'utf8'));
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return {};
    return parsed as DenialLedger;
  } catch {
    return {}; // silent: fail-open — a corrupt ledger just starts over
  }
}

function writeLedger(path: string, ledger: DenialLedger): void {
  try {
    mkdirSync(dirname(path), { recursive: true });
    // pid-suffixed tmp: two hooks in one session can be in flight at once,
    // and a shared `.tmp` name would let them clobber each other's rename.
    const tmp = `${path}.${process.pid}.tmp`;
    writeFileSync(tmp, `${JSON.stringify(ledger, null, 2)}\n`, 'utf8');
    renameSync(tmp, path);
  } catch {
    // silent: fail-open — losing the count costs an escalation, not a session
  }
}

/**
 * Drop expired entries, then trim to the cap by keeping the most recent.
 * Exported for tests; callers get this applied automatically.
 */
export function pruneLedger(ledger: DenialLedger, nowMs: number): DenialLedger {
  const live = Object.entries(ledger).filter(
    ([, e]) => e && typeof e.lastMs === 'number' && nowMs - e.lastMs < DENIAL_TTL_MS,
  );
  live.sort((a, b) => b[1].lastMs - a[1].lastMs);
  return Object.fromEntries(live.slice(0, MAX_ENTRIES));
}

/**
 * Record one denial of `command` and return how many times this session has
 * now been denied for it. First denial returns 1, so `>= 2` is "the caller is
 * re-sending".
 *
 * `sessionId` empty (no session in the hook input) disables tracking and
 * always returns 1 — without a session key the ledger would pool unrelated
 * runs together and escalate on a first attempt.
 */
export function recordDenial(
  command: string,
  repoSlug: string,
  sessionId: string,
  nowMs: number = Date.now(),
  home: string = homedir(),
): number {
  if (!sessionId || !repoSlug) return 1;

  try {
    const path = getDenialLedgerPath(repoSlug, sessionId, home);
    const ledger = pruneLedger(readLedger(path), nowMs);

    const key = fnv1aHash(command);
    const head = command.slice(0, HEAD_LEN);
    const prior = ledger[key];
    // Same key but different bytes = hash collision. Treat as a new command.
    const isSame = prior && prior.head === head;

    const entry: DenialEntry = isSame
      ? { count: prior.count + 1, firstMs: prior.firstMs, lastMs: nowMs, head }
      : { count: 1, firstMs: nowMs, lastMs: nowMs, head };

    ledger[key] = entry;
    writeLedger(path, ledger);
    return entry.count;
  } catch {
    return 1; // silent: fail-open — never let bookkeeping break the guard
  }
}
